"""Tests for daterange.parse_range, covering every rule in SPEC.md."""
import datetime
import unittest

from daterange import parse_range

D = datetime.date


class TestDateToDate(unittest.TestCase):
    def test_two_dates(self):
        self.assertEqual(
            parse_range("2026-10-01..2026-10-31"),
            (D(2026, 10, 1), D(2026, 10, 31)),
        )

    def test_same_date_twice(self):
        self.assertEqual(
            parse_range("2026-10-01..2026-10-01"),
            (D(2026, 10, 1), D(2026, 10, 1)),
        )

    def test_leap_day(self):
        self.assertEqual(
            parse_range("2024-02-29..2024-03-01"),
            (D(2024, 2, 29), D(2024, 3, 1)),
        )

    def test_spaces_around_text(self):
        self.assertEqual(
            parse_range("  2026-10-01..2026-10-31  "),
            (D(2026, 10, 1), D(2026, 10, 31)),
        )

    def test_spaces_around_separator(self):
        self.assertEqual(
            parse_range("2026-10-01 .. 2026-10-31"),
            (D(2026, 10, 1), D(2026, 10, 31)),
        )

    def test_several_spaces_around_separator(self):
        self.assertEqual(
            parse_range("2026-10-01   ..   2026-10-31"),
            (D(2026, 10, 1), D(2026, 10, 31)),
        )

    def test_tabs_around_separator(self):
        self.assertEqual(
            parse_range("\t2026-10-01\t..\t2026-10-31\t"),
            (D(2026, 10, 1), D(2026, 10, 31)),
        )


class TestMonth(unittest.TestCase):
    def test_thirty_one_day_month(self):
        self.assertEqual(parse_range("2026-10"), (D(2026, 10, 1), D(2026, 10, 31)))

    def test_thirty_day_month(self):
        self.assertEqual(parse_range("2026-09"), (D(2026, 9, 1), D(2026, 9, 30)))

    def test_february_non_leap_year(self):
        self.assertEqual(parse_range("2026-02"), (D(2026, 2, 1), D(2026, 2, 28)))

    def test_february_leap_year(self):
        self.assertEqual(parse_range("2024-02"), (D(2024, 2, 1), D(2024, 2, 29)))

    def test_january(self):
        self.assertEqual(parse_range("2026-01"), (D(2026, 1, 1), D(2026, 1, 31)))

    def test_december(self):
        self.assertEqual(parse_range("2026-12"), (D(2026, 12, 1), D(2026, 12, 31)))

    def test_surrounding_spaces(self):
        self.assertEqual(parse_range("  2026-10  "), (D(2026, 10, 1), D(2026, 10, 31)))


class TestIsoWeek(unittest.TestCase):
    def test_spec_example(self):
        self.assertEqual(parse_range("2026-W44"), (D(2026, 10, 26), D(2026, 11, 1)))

    def test_week_one_may_start_in_previous_year(self):
        self.assertEqual(parse_range("2026-W01"), (D(2025, 12, 29), D(2026, 1, 4)))

    def test_week_fifty_three_in_long_year(self):
        self.assertEqual(parse_range("2026-W53"), (D(2026, 12, 28), D(2027, 1, 3)))

    def test_week_fifty_three_ends_in_next_year(self):
        self.assertEqual(parse_range("2020-W53"), (D(2020, 12, 28), D(2021, 1, 3)))

    def test_week_single_digit_week_number(self):
        self.assertEqual(parse_range("2026-W05"), (D(2026, 1, 26), D(2026, 2, 1)))

    def test_surrounding_spaces(self):
        self.assertEqual(parse_range(" 2026-W44 "), (D(2026, 10, 26), D(2026, 11, 1)))


class TestYear(unittest.TestCase):
    def test_whole_year(self):
        self.assertEqual(parse_range("2026"), (D(2026, 1, 1), D(2026, 12, 31)))

    def test_leap_year(self):
        self.assertEqual(parse_range("2024"), (D(2024, 1, 1), D(2024, 12, 31)))

    def test_surrounding_spaces(self):
        self.assertEqual(parse_range("  2026\t"), (D(2026, 1, 1), D(2026, 12, 31)))


class TestOpenEnds(unittest.TestCase):
    def test_open_start(self):
        self.assertEqual(parse_range("..2026-10-01"), (None, D(2026, 10, 1)))

    def test_open_end(self):
        self.assertEqual(parse_range("2026-10-01.."), (D(2026, 10, 1), None))

    def test_open_start_with_spaces(self):
        self.assertEqual(parse_range("  .. 2026-10-01 "), (None, D(2026, 10, 1)))

    def test_open_end_with_spaces(self):
        self.assertEqual(parse_range(" 2026-10-01 ..  "), (D(2026, 10, 1), None))

    def test_open_start_of_month_expands_to_last_day(self):
        self.assertEqual(parse_range("..2026-10"), (None, D(2026, 10, 31)))

    def test_open_end_of_month_expands_to_first_day(self):
        self.assertEqual(parse_range("2026-10.."), (D(2026, 10, 1), None))

    def test_open_end_of_week(self):
        self.assertEqual(parse_range("2026-W44.."), (D(2026, 10, 26), None))

    def test_open_end_of_year(self):
        self.assertEqual(parse_range("..2026"), (None, D(2026, 12, 31)))


class TestMixedTokens(unittest.TestCase):
    def test_month_to_month(self):
        self.assertEqual(parse_range("2026-10..2026-12"), (D(2026, 10, 1), D(2026, 12, 31)))

    def test_date_to_month(self):
        self.assertEqual(parse_range("2026-10-15..2026-12"), (D(2026, 10, 15), D(2026, 12, 31)))

    def test_month_to_date(self):
        self.assertEqual(parse_range("2026-11..2026-11-15"), (D(2026, 11, 1), D(2026, 11, 15)))

    def test_week_to_month(self):
        self.assertEqual(parse_range("2026-W44..2026-11"), (D(2026, 10, 26), D(2026, 11, 30)))

    def test_year_to_month(self):
        self.assertEqual(parse_range("2026..2026-03"), (D(2026, 1, 1), D(2026, 3, 31)))

    def test_single_date(self):
        self.assertEqual(parse_range("2026-10-01"), (D(2026, 10, 1), D(2026, 10, 1)))

    def test_result_is_a_pair_of_dates(self):
        start, end = parse_range("2026-W44")
        self.assertIsInstance(start, datetime.date)
        self.assertIsInstance(end, datetime.date)

    def test_open_end_is_none(self):
        start, end = parse_range("2026-10-01..")
        self.assertIsInstance(start, datetime.date)
        self.assertIsNone(end)


class TestErrors(unittest.TestCase):
    def assert_invalid(self, text):
        with self.assertRaises(ValueError):
            parse_range(text)

