import calendar, datetime, random, string, itertools
from daterange import parse_range

# week expansion cross-check against stdlib for every year 1..2200 (sample) and week 1..53
bad = 0
for year in list(range(1, 60)) + list(range(1990, 2060)) + list(range(9980, 10000)):
    for week in range(1, 54):
        try:
            exp = (datetime.date.fromisocalendar(year, week, 1),
                   datetime.date.fromisocalendar(year, week, 7))
            ok = True
        except (ValueError, OverflowError):
            ok = False
        try:
            got = parse_range("%04d-W%02d" % (year, week))
        except ValueError:
            got = None
        if ok and got != exp:
            bad += 1; print("MISMATCH", year, week, got, exp)
        if not ok and got is not None:
            bad += 1; print("SHOULD FAIL", year, week, got)
print("week mismatches:", bad)

# month cross-check
for year in range(1, 9999, 37):
    for month in range(1, 13):
        exp = (datetime.date(year, month, 1), datetime.date(year, month, calendar.monthrange(year, month)[1]))
        assert parse_range("%04d-%02d" % (year, month)) == exp, (year, month)
print("months ok")

# edge cases
for t in ["9999-W52", "9999-W01", "0001-W01", "9999", "9999-12", "2026-10-01 .... 2026-10-31",
          "2026-10-01 ....2026-10-31", "2026-10-01\u00a0..\u00a02026-10-31", "  ", "\u2028",
          "2026-10-01..2026-10-01", "2026-W53..2027-W01", "..", ".. .."]:
    try:
        print(repr(t), "->", parse_range(t))
    except Exception as e:
        print(repr(t), "-> raises", type(e).__name__, e)

# fuzz: only ValueError should ever escape
alphabet = string.digits + "-Ww. :\t" 
random.seed(0)
for _ in range(20000):
    s = "".join(random.choice(alphabet) for _ in range(random.randint(0, 14)))
    try:
        parse_range(s)
    except ValueError:
        pass
    except Exception as e:
        print("UNEXPECTED", repr(s), type(e).__name__, e); break
else:
    print("fuzz ok")
EOF","description":"Cross-check weeks, months, edges and fuzz"}

